INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('f8171114-22fc-4e90-8d42-17aebd9f5a86', '00000000-0000-4000-8000-000000000001', 'BEAUTY OF JOSEON - Matte Sun Stick - 18g', 'BEAUTY OF JOSEON', 'BATH_BODY', 'La beauté du bâton solaire mat Joseon : Mugwort + Camelia a été développée avec Ramón, influenceur et chimiste cosmétique. L''objectif était de créer un stick solaire avec SPF 50+ PA++++ qui s''applique magnifiquement sur le maquillage et combat le gras tout au long de la journée. La poudre de silice aide à absorber l''excès de sébum afin que votre peau soit plus douce, plus lisse et moins grasse après utilisation. Maintenez l’hydratation et protégez votre peau avec une puissante couverture SPF. Ingrédient clé L''armoise a été un ingrédient important tout au long de l''histoire de la médecine asiatique. L''Artemisia capillaris a des propriétés rafraîchissantes et est utilisée comme médicament thérapeutique depuis l''Antiquité. Zéro dominante blanche. Certifié végétalien.
