INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('9e728fc5-5e12-4703-b602-4b37d825d8b4', '00000000-0000-4000-8000-000000000001', 'MEDICUBE - Red Acne Body Wash Off Peeling Shot - 110g', 'MEDICUBE', 'BATH_BODY', 'Un exfoliant corporel à rincer facile à utiliser qui aide à lisser et à adoucir les zones rugueuses comme le dos, la poitrine, les bras et les jambes. Il suffit de vaporiser, de masser doucement et de rincer après une minute. Idéal pour une utilisation estivale, il aide à rafraîchir la peau exposée à la chaleur, à la sueur et à l''humidité, ce qui lui permet de se sentir propre et confortable. Les particules fines de formule micro-encapsulées aident à fournir des ingrédients actifs uniformément sur toute la peau pour répondre aux principaux problèmes de peau du corps tels que l''excès d''huile, les pores obstrués et la matité.
