INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('3110e8f7-44f7-4b58-89b1-3aba0f0680ea', '00000000-0000-4000-8000-000000000001', 'SOL DE JANEIRO - MINI Cheirosa 87 Rio Radiance Hair & Body Perfume Mist - 30ml', 'SOL DE JANEIRO', 'FRAGRANCE', 'Rio Radiance Perfume Mist vous ramène à vos vacances préférées - où des notes nostalgiques de leite de coco, de tubéreuse solaire et de sable chaud laissent s''attarder les jours de plage insouciants. Au Brésil, le secret de beauté essentiel est d''être cheirosa (sheh-ro-zah), ce qui signifie toujours sentir délicieux. Un parfum floral solaire mélangeant du lait de coco crémeux et des fleurs blanches propres qui évoquent la chaleur du soleil sur la peau - l''incarnation de la nostalgie. Formulé sans phtalates. Vegan et sans cruauté
