INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('190deea3-1f11-4c39-9d8b-808bf27e213c', '00000000-0000-4000-8000-000000000001', 'INVISIBOBBLE - Spirale à Cheuveux Élégante Slim Original - Bronze Me Pretty ( 3pcs )', 'INVISIBOBBLE', 'BATH_BODY', 'L''élastique en spirale INVISIBOBBLE - Bronze Me Pretty (3pcs) offre une tenue irrésistible sans abîmer vos cheveux. Sa forme unique répartit la pression pour éviter les marques et les maux de tête, tout en réduisant la casse de 31%. Idéal pour tous les types de cheveux, il est le meilleur allié pour des chignons et queues de cheval parfaits.
