INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('f26ae56e-1189-440e-8145-447be350c241', '00000000-0000-4000-8000-000000000001', 'COLOR WOW - Mini Dream Filter - Avant-Shampooing - 50ml', 'COLOR WOW', 'HYGIENE', 'Ce soin pré-shampoing révolutionnaire filtre les minéraux, généralement présents dans l''eau courante et qui nuisent à l''intensité et à la beauté de votre couleur de cheveux. Sa formule unique en spray combine 2 filtres moléculaires et 2 filtres polymères (jamais utilisés dans aucun autre produit capillaire) pour éliminer en douceur, en toute sécurité et rapidement les minéraux comme le chlore ou le calcaire.
