INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('060bd15e-43fa-4c8f-9a67-65a826fc699f', '00000000-0000-4000-8000-000000000001', 'COLOR WOW - Pop and Lock Shellac - Sérum revitalisant pour Cheveux - 55ml', 'COLOR WOW', 'HYGIENE', 'Le sérum Pop and Lock Crystallite Shellac Color Wow est un sérum à la formule légère qui combine deux technologies : une huile et un sérum, afin d''hydrater, nourrir, lisser et faire briller le cheveu.
