INSERT INTO products (id, organization_id, name, brand, category, description, image_url, source_url, retail_visible) VALUES ('54344673-6c37-4035-ace1-1aeb7b99de77', '00000000-0000-4000-8000-000000000001', 'Gisou - Honey Milk Active Repair - Brume après-shampoing sans rinçage réparatrice', 'Gisou', 'HYGIENE', 'Gisou - Honey Milk Active Repair est une brume après-shampoing sans rinçage, avec une efficacité prouvée pour démêler et hydrater la fibre capillaire. Enrichie en miel Mirsalehi et protéines de lait, elle assure une réparation moléculaire, préservant la kératine tout en lissant les frisottis et en augmentant la brillance, offrant des résultats visibles au fil du temps.
